"""Explicitly requested fictional cases, stored only in the presentation database."""
import sys,json,sqlite3
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'backend'))
import main
from services.phone_auth import demo_connection,digest,phone_number,demo_path
from services.screening import FIELDS,DEFAULT_RUBRIC

CASES=[
 ('Asha Demo','School uniform tailoring','Pune','School uniforms and alterations',8.2,'SUBMITTED'),
 ('Ravi Demo','Home tiffin service','Mumbai','Fresh vegetarian lunch boxes',7.4,'ADMIN_REVIEW'),
 ('Meena Demo','Handmade soap workshop','Nashik','Handmade soap gift packs',6.1,'PROGRAM_DECIDED'),
 ('Kabir Demo','Mobile phone repair','Thane','Mobile phone repairs',5.0,'CLARIFICATION'),
 ('Lata Demo','Millet snack stall','Solapur','Fresh millet snacks',3.8,'PROVISIONALLY_SCORED'),
]
def seed():
    with demo_connection() as db:
        db.execute('CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY,owner TEXT NOT NULL,assessor TEXT,status TEXT NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL)')
        def entity(kind,eid,body):db.execute('INSERT OR IGNORE INTO program_entities VALUES(?,?,?)',(kind,eid,json.dumps(body)))
        def account(name,role,number):
            phone=phone_number(number);aid=role+'_'+digest(phone)[:24]
            entity('account',aid,{'id':aid,'name':name,'role':role,'phone':phone,'active':True,'presentation':True,'synthetic':True})
            entity('profile',aid,{'id':aid,'name':name,'preferred_language':'en','synthetic':True})
            return aid
        assessor=account('Synthetic Demo Assessor','assessor','+12025550110')
        account('Synthetic Demo Program Manager','admin','+12025550119')
        cohort='synthetic-demo-cohort'
        entity('cohort',cohort,{'id':cohort,'name':'Synthetic presentation examples','status':'ACTIVE','synthetic':True})
        entity('capacity',assessor,{'id':assessor,'maximum':20,'preferred':20,'available':True,'regions':[],'trades':[],'synthetic':True})
        for index,(name,title,region,product,overall,state) in enumerate(CASES):
            owner=account(name,'beneficiary','+1202555010'+str(index+1))
            sid='synthetic-demo-case-'+str(index+1)
            now=main.now()
            values={
             'overview.businessName':title,'overview.productService':product,'overview.proposedLocation':region,'overview.businessStage':'Planning a pilot',
             'market.targetCustomers':'Local households and nearby institutions','market.customerProblem':'Customers need a convenient local service','market.demandEvidence':'Five fictional customers expressed interest; no real survey was conducted','market.competition':'Two fictional competing providers','market.differentiation':'Convenient local delivery and customization','market.salesChannels':'Local referrals and direct orders',
             'finance.initialInvestment':'INR 100000','finance.availableCapital':'INR 40000','finance.unitCost':'INR 60 per item','finance.sellingPrice':'INR 100 per item','finance.expectedSales':'500 items per month','finance.revenueAssumptions':'INR 50000 per month','finance.monthlyExpenses':'INR 10000 monthly fixed costs','finance.requestedFunding':'INR 60000','finance.fundingSources':'Personal savings and a proposed loan; no approval exists',
             'operations.equipment':'Basic tools and a work table','operations.suppliers':'A fictional local wholesaler','operations.capacity':'500 items per month','operations.skills':'One year of illustrative training','operations.staffing':'One owner and one assistant','operations.distribution':'Local pickup and delivery','operations.rawMaterials':'Materials appropriate to the described product',
             'risk.marketRisks':'Demand may be seasonal','risk.financialRisks':'Payments may be delayed','risk.operationalRisks':'Equipment may need maintenance','risk.mitigation':'Start with a small pilot and record expenses','risk.compliance':'Check local registration requirements before launch'}
            pitch='SYNTHETIC DEMO — fictional information, not a real application. '+name+' proposes '+product+' in '+region+'. '+ ' '.join(values.values())
            facts={key:{'field':key,'value':value,'status':'PROVIDED','confirmed':True,'claims':[{'value':value,'evidence':value,'source_id':'pitch','amount':None,'currency':None,'unit':None}],'validation':{'valid':True,'errors':[]},'method':'SYNTHETIC_FIXTURE'} for key,value in values.items()}
            domains={key:{'weight':weight,'rating':overall/2,'supportedFields':fields,'missingFields':[]} for key,(weight,fields) in DEFAULT_RUBRIC.items()}
            score={'assessmentType':'SYNTHETIC_DEMO_SCORE','overallScore':overall,'completeness':100,'confidence':'ILLUSTRATIVE','feasibility':'Not evaluated by a live model','status':'SYNTHETIC','scoreMeaning':'Predefined fictional demonstration score. Not generated by Qwen and not an approval.','domains':domains,'unitContribution':None,'stale':False}
            questions=[{'id':sid+'-q-'+str(i),'field':fields[0],'text':'Please explain this part of your proposed business.','rationale':'Synthetic assessment example.','guidance':'Review the fictional source.','status':'answered','answer':values[fields[0]],'translations':{'en':'Please explain this part of your proposed business.'}} for i,(_,fields) in enumerate(DEFAULT_RUBRIC.values())]
            record={'id':sid,'owner':owner,'assessor':assessor,'title':'[SYNTHETIC] '+title,'synthetic':True,'syntheticBeneficiary':name,'language':'en','region':region,'cohortId':cohort,'trade':title,'inputType':'text','sources':[{'id':'pitch','original':pitch,'english':pitch,'language':'en','detectedLanguage':'en','translationUncertain':False}],'facts':facts,'questions':questions,'maxQuestions':8,'state':state,'history':[{'state':state,'at':now}],'createdAt':now,'updatedAt':now,'revision':1,'currentScore':score,'finalScore':score,'report':{'strengths':['Illustrative local service concept'],'weaknesses':['Synthetic evidence has not been validated'],'recommendations':['Validate real demand before making a business decision'],'explanation':'Fictional presentation example; the score is predefined, not a live AI assessment.','remainingUnknowns':[]}}
            if state in ('SUBMITTED','ADMIN_REVIEW','PROGRAM_DECIDED'):record['submittedAt']=now
            if state in ('ADMIN_REVIEW','PROGRAM_DECIDED'):record['recommendation']={'recommendation':'FURTHER_MENTORING_REQUIRED','reason':'Synthetic example: validate demand and operating costs.','assessor':assessor,'at':now}
            if state=='PROGRAM_DECIDED':record['adminDecision']={'decision':'RETURN_FOR_MENTORING','reason':'Synthetic example: complete a small pilot first.','at':now}
            db.execute('INSERT OR IGNORE INTO submissions VALUES(?,?,?,?,?,?)',(sid,owner,assessor,state,1,json.dumps(record)))
    print('Five synthetic beneficiary cases and two synthetic staff accounts are ready. Existing records were not overwritten.')
if __name__=='__main__':seed()
